namespace PersonalFinance.BuildingBlocks.Domain;

public abstract class Entity
{
    protected Entity(Guid id)
    {
        Id = id;
    }

    /// <summary>For the persistence layer.</summary>
    protected Entity()
    {
    }

    public Guid Id { get; private set; }

    /// <summary>Time-ordered identifier generated by the application, so no database round trip is needed.</summary>
    public static Guid NewId() => Guid.CreateVersion7();
}

/// <summary>
/// Marker for something that happened inside an aggregate. It is declared in the module's Domain when only that
/// module reacts to it, and in its Contracts when another module does.
/// </summary>
public interface IDomainEvent;

public interface IHasDomainEvents
{
    IReadOnlyCollection<IDomainEvent> DomainEvents { get; }

    void ClearDomainEvents();
}

public abstract class AggregateRoot : Entity, IHasDomainEvents
{
    private readonly List<IDomainEvent> _domainEvents = [];

    protected AggregateRoot(Guid id) : base(id)
    {
    }

    /// <summary>For the persistence layer.</summary>
    protected AggregateRoot()
    {
    }

    public IReadOnlyCollection<IDomainEvent> DomainEvents => _domainEvents.AsReadOnly();

    public void ClearDomainEvents() => _domainEvents.Clear();

    protected void Raise(IDomainEvent domainEvent) => _domainEvents.Add(domainEvent);
}

/// <summary>
/// Private data: it belongs to one user inside one workspace. The persistence layer filters every
/// query on these two columns, so workspace membership alone never grants access.
/// </summary>
public interface IOwned
{
    Guid WorkspaceId { get; }

    Guid OwnerUserId { get; }
}
